import { MeshBasicNodeMaterial } from 'three/webgpu';
import { vec3, uv, mix, smoothstep, time } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Vector3, Color } = ctx.THREE;

  // ============ SCENE SETUP ============
  const root = new Group();
  root.position.set(0, 0, 0);
  root.rotation.set(0, 0, 0);
  root.scale.set(1, 1, 1);

  const timelines = [];
  const cleanupFns = [];

  // ============ BACKDROP PLANE (GRADIENT) ============
  const backdropGeo = new PlaneGeometry(7, 5.5, 16, 16);
  const backdropUV = uv();

  // Engineered vertical gradient: #0b0b10 (bottom) -> #14141a (top)
  const gradStart = new Color('#0b0b10');
  const gradEnd = new Color('#14141a');
  const gradientNode = mix(
    vec3(gradStart.r, gradStart.g, gradStart.b),
    vec3(gradEnd.r, gradEnd.g, gradEnd.b),
    backdropUV.y
  );

  // 1.5% monochrome grain via noise
  const grainIntensity = 0.015;
  const grainNode = mix(
    gradientNode,
    vec3(0.5),
    smoothstep(0.45, 0.55, smoothstep(0.0, 1.0, time.mul(0.5).fract()))
  );

  const backdropMat = new MeshBasicNodeMaterial({
    colorNode: grainNode,
    toneMapped: false,
  });

  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -0.5;
  root.add(backdrop);

  // ============ TEXT RENDERING ============
  const textBlocks = [];

  // Kicker: "NOVA ATELIER / JOURNAL"
  const kicker = ctx.fontAtlas.createText('NOVA ATELIER / JOURNAL', {
    fontSize: 18,
    fontWeight: 700,
    color: '#e8ecf2',
    align: 'left',
    letterSpacingPx: 0.12 * 18 * 0.01, // 0.12em
  });
  kicker.position.set(-3.1, 1.7, 0.1);
  root.add(kicker);
  textBlocks.push({ obj: kicker, delay: 0 });

  // Hero line 1: "PRECISION IS"
  const heroLine1 = ctx.fontAtlas.createText('PRECISION IS', {
    fontSize: 124,
    fontWeight: 600,
    color: '#e8ecf2',
    align: 'left',
    letterSpacingPx: -0.015 * 124 * 0.01, // -0.015em
  });
  heroLine1.position.set(-3.1, 0.9, 0.1);
  root.add(heroLine1);
  textBlocks.push({ obj: heroLine1, delay: 80 });

  // Hero line 2: "A HABIT."
  const heroLine2 = ctx.fontAtlas.createText('A HABIT.', {
    fontSize: 124,
    fontWeight: 600,
    color: '#e8ecf2',
    align: 'left',
    letterSpacingPx: -0.015 * 124 * 0.01,
  });
  heroLine2.position.set(-3.1, 0.25, 0.1);
  root.add(heroLine2);
  textBlocks.push({ obj: heroLine2, delay: 160 });

  // Accent underline rule (2.2 x 0.05 units, #ff2a38, emissive 1.2)
  const ruleGeo = new PlaneGeometry(2.2, 0.05);
  const ruleMat = new MeshBasicNodeMaterial({
    color: new Color('#ff2a38'),
    emissive: new Color('#ff2a38'),
    emissiveIntensity: 1.2,
    toneMapped: false,
  });
  const rule = new Mesh(ruleGeo, ruleMat);
  rule.position.set(-3.1 + 2.2 * 0.5, -0.15, 0.1);
  rule.scale.x = 0; // Will animate from 0 to 1
  root.add(rule);
  textBlocks.push({ obj: rule, isRule: true, delay: 240 });

  // Body paragraph
  const body = ctx.fontAtlas.createText(
    'Notes from the bench: tolerances, tempering, and the case for slower watchmaking.',
    {
      fontSize: 26,
      fontWeight: 400,
      color: '#e8ecf2',
      align: 'left',
      maxWidthPx: 4.5 * 100, // ~4.5 units
      letterSpacingPx: 0,
    }
  );
  body.position.set(-3.1, -0.8, 0.1);
  root.add(body);
  textBlocks.push({ obj: body, delay: 320 });

  // Caption
  const caption = ctx.fontAtlas.createText('ISSUE 12 / JULY 2026', {
    fontSize: 18,
    fontWeight: 400,
    color: '#e8ecf2',
    align: 'left',
    letterSpacingPx: 0.08 * 18 * 0.01, // 0.08em
  });
  caption.position.set(-3.1, -1.9, 0.1);
  root.add(caption);
  textBlocks.push({ obj: caption, delay: 400 });

  // ============ LETTERPRESS SHADOW (print-depth trick) ============
  // Duplicate hero lines at z-0.02 in #16161d for shadow edge
  const shadowLine1 = ctx.fontAtlas.createText('PRECISION IS', {
    fontSize: 124,
    fontWeight: 600,
    color: '#16161d',
    align: 'left',
    letterSpacingPx: -0.015 * 124 * 0.01,
  });
  shadowLine1.position.set(-3.1 - 0.02, 0.9 - 0.02, 0);
  root.add(shadowLine1);
  cleanupFns.push(() => {
    shadowLine1.traverse((node) => {
      if (node.material) node.material.dispose();
      if (node.geometry) node.geometry.dispose();
    });
  });

  const shadowLine2 = ctx.fontAtlas.createText('A HABIT.', {
    fontSize: 124,
    fontWeight: 600,
    color: '#16161d',
    align: 'left',
    letterSpacingPx: -0.015 * 124 * 0.01,
  });
  shadowLine2.position.set(-3.1 - 0.02, 0.25 - 0.02, 0);
  root.add(shadowLine2);
  cleanupFns.push(() => {
    shadowLine2.traverse((node) => {
      if (node.material) node.material.dispose();
      if (node.geometry) node.geometry.dispose();
    });
  });

  // ============ ENTRANCE ANIMATION ============
  // Rise-in per block: y +0.4 to 0, opacity 0 to 1, 700ms, cubic-bezier(0.215,0.61,0.355,1)
  // 80ms stagger between blocks
  // Rule draws scaleX 0 to 1 over 500ms after hero lands

  const animTimeline = gsap.timeline({ paused: false });
  timelines.push(animTimeline);

  textBlocks.forEach((block, idx) => {
    if (block.isRule) {
      // Rule animates after hero (at 700ms + 160ms delay for line 2)
      animTimeline.to(
        block.obj.scale,
        {
          x: 1,
          duration: 0.5,
          ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)',
        },
        0.86 // Start after hero line 2 lands (700ms + 160ms stagger)
      );
    } else {
      const startY = block.obj.position.y;
      block.obj.position.y += 0.4;
      block.obj.traverse((node) => {
        if (node.material && node.material.opacity !== undefined) {
          node.material.opacity = 0;
        }
      });

      animTimeline.to(
        block.obj.position,
        {
          y: startY,
          duration: 0.7,
          ease: 'cubic-bezier(0.215, 0.61, 0.355, 1)',
        },
        block.delay * 0.001 // Convert ms to timeline position
      );

      block.obj.traverse((node) => {
        if (node.material && node.material.opacity !== undefined) {
          animTimeline.to(
            node.material,
            { opacity: 1, duration: 0.7, ease: 'cubic-bezier(0.215, 0.61, 0.355, 1)' },
            block.delay * 0.001
          );
        }
      });
    }
  });

  // ============ CLEANUP ============
  root.userData.cleanup = () => {
    timelines.forEach((tl) => {
      if (tl && tl.kill) tl.kill();
    });

    cleanupFns.forEach((fn) => fn());

    root.traverse((node) => {
      if (node.material) {
        if (Array.isArray(node.material)) {
          node.material.forEach((mat) => mat.dispose());
        } else {
          node.material.dispose();
        }
      }
      if (node.geometry) {
        node.geometry.dispose();
      }
    });
  };

  root.userData.handlers = {};

  return root;
}
